import sys

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0].strip())
    queue = [None] * n
    front = -1
    rear = -1

    def enqueue(x):
        nonlocal front, rear
        if (rear + 1) % n == front:
            print("Queue Overflow")
            return
        if front == -1:
            front = 0
            rear = 0
        else:
            rear = (rear + 1) % n
        queue[rear] = x

    def dequeue():
        nonlocal front, rear
        if front == -1:
            print("Queue Underflow")
            return
        val = queue[front]
        if front == rear:
            front = -1
            rear = -1
        else:
            front = (front + 1) % n
        return val

    def display():
        nonlocal front, rear
        if front == -1:
            return
        result = []
        i = front
        while True:
            result.append(str(queue[i]))
            if i == rear:
                break
            i = (i + 1) % n
        print(' '.join(result))

    for i in range(1, len(data)):
        line = data[i].strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == 'enqueue':
            x = int(parts[1])
            enqueue(x)
        elif parts[0] == 'dequeue':
            dequeue()
        elif parts[0] == 'display':
            display()

if __name__ == "__main__":
    main()
